function push(stack, value):
  stack[stack.size] = value
  stack.size = stack.size + 1

function enqueue(queue, value):
  queue.tail = (queue.tail + 1) % queue.capacity
  queue.data[queue.tail] = value

function sum(arr):
  total = 0
  for i in 0..arr.length:
    total = total + arr[i]
  return total

function find(arr, target):
  for i in 0..arr.length:
    if arr[i] == target:
      return i
  return -1

function maxValue(arr):
  best = arr[0]
  for i in 1..arr.length:
    if arr[i] > best:
      best = arr[i]
  return best

function countEvens(arr):
  count = 0
  for x in arr:
    if x % 2 == 0:
      count = count + 1
  return count

function binarySearch(arr, target):
  left = 0
  right = arr.length - 1
  while left <= right:
    mid = (left + right) / 2
    if arr[mid] == target:
      return mid
    if arr[mid] < target:
      left = mid + 1
    else:
      right = mid - 1
  return -1

function steps(n):
  count = 0
  while n > 1:
    n = n / 2
    count = count + 1
  return count

function search(arr, target, left, right):
  if left > right:
    return -1
  mid = (left + right) / 2
  if arr[mid] == target:
    return mid
  if arr[mid] < target:
    return search(arr, target, mid + 1, right)
  return search(arr, target, left, mid - 1)

function bubbleSort(arr):
  n = arr.length
  for i in 0..n:
    for j in 0..n - i - 1:
      if arr[j] > arr[j + 1]:
        swap(arr[j], arr[j + 1])

function selectionSort(arr):
  n = arr.length
  for i in 0..n:
    minIdx = i
    for j in i + 1..n:
      if arr[j] < arr[minIdx]:
        minIdx = j
    swap(arr[i], arr[minIdx])

function countPairs(arr):
  count = 0
  for i in 0..arr.length:
    for j in i + 1..arr.length:
      count = count + 1
  return count

function insertionSort(arr):
  for i in 1..arr.length:
    key = arr[i]
    j = i - 1
    while j >= 0 and arr[j] > key:
      arr[j + 1] = arr[j]
      j = j - 1
    arr[j + 1] = key

