function heapSort(arr):
  buildMaxHeap(arr)
  for i in arr.length - 1 down to 1:
    swap(arr[0], arr[i])
    heapify(arr, 0, i)

function quickSort(arr, low, high):
  if low < high:
    pivot = partition(arr, low, high)
    quickSort(arr, low, pivot - 1)
    quickSort(arr, pivot + 1, high)
// pivot sempre o menor elemento

function fib(n):
  if n <= 1:
    return n
  return fib(n - 1) + fib(n - 2)

function subsets(arr, index, current):
  if index == arr.length:
    print(current)
    return
  subsets(arr, index + 1, current)
  subsets(arr, index + 1, current + [arr[index]])

function permute(arr, used, path):
  if path.length == arr.length:
    print(path)
    return
  for i in 0..arr.length:
    if not used[i]:
      used[i] = true
      permute(arr, used, path + [arr[i]])
      used[i] = false

function multiply(A, B):
  n = A.length
  C = matrix(n, n)
  for i in 0..n:
    for j in 0..n:
      for k in 0..n:
        C[i][j] = C[i][j] + A[i][k] * B[k][j]
  return C

function dfs(node):
  if node == null:
    return
  visit(node)
  dfs(node.left)
  dfs(node.right)

function bfs(root):
  queue = [root]
  while queue not empty:
    node = queue.popFront()
    for child in node.children:
      queue.push(child)

function ternarySearch(arr, target, left, right):
  if left > right:
    return -1
  third = (right - left) / 3
  mid1 = left + third
  mid2 = right - third
  if target < arr[mid1]:
    return ternarySearch(arr, target, left, mid1 - 1)
  if target > arr[mid2]:
    return ternarySearch(arr, target, mid2 + 1, right)
  return ternarySearch(arr, target, mid1 + 1, mid2 - 1)

function hasDuplicate(arr):
  seen = set()
  for x in arr:
    if x in seen:
      return true
    seen.add(x)
  return false

function twoSum(arr, target):
  seen = map()
  for i in 0..arr.length:
    need = target - arr[i]
    if need in seen:
      return [seen[need], i]
    seen[arr[i]] = i

function gcd(a, b):
  while b != 0:
    temp = b
    b = a % b
    a = temp
  return a

function majority(arr):
  candidate = null
  count = 0
  for x in arr:
    if count == 0:
      candidate = x
      count = 1
    else if x == candidate:
      count = count + 1
    else:
      count = count - 1
  return candidate

function findMin(arr):
  minVal = arr[0]
  for i in 1..arr.length:
    if arr[i] < minVal:
      minVal = arr[i]
  return minVal
